def book_room(conn, room_id, from_, to):
    with conn:                                  # commits on success, rolls back on exception
        row = conn.execute(
            "SELECT available FROM rooms WHERE id = ?", (room_id,)
        ).fetchone()
        if row is None or row["available"] == 0:
            raise NotAvailable(room_id)
        conn.execute(
            "INSERT INTO bookings (room_id, from_, to_) VALUES (?, ?, ?)",
            (room_id, from_, to),
        )

